import {causes} from './workshop-repair-model.mjs';
import {repairExamGrade} from './workshop-repair-exam-model.mjs';
export function guidedCaseErrors(c){const g=repairExamGrade(c),ids=new Set([...causes(c.repair),...c.repair.actions.map(a=>a.id)]);return [...ids].map(id=>({id,unnecessary:c.repair.actions.filter(a=>a.id===id&&!a.useful).length,missing:g.remaining.includes(id),measurements:!g.evidence&&causes(c.repair).includes(id)})).filter(x=>x.unnecessary||x.missing||x.measurements);}
export function guidedExamMastery(rows){const groups=new Map();for(const e of [...rows].sort((a,b)=>Date.parse(a.finished)-Date.parse(b.finished)))for(const [index,c]of e.cases.entries()){const ids=new Set([...causes(c.repair),...c.repair.actions.map(a=>a.id)]),errors=guidedCaseErrors(c);for(const id of ids){const key=c.repair.kind+':'+id;if(!groups.has(key))groups.set(key,{key,kind:c.repair.kind,id,cases:[]});groups.get(key).cases.push({clean:!errors.some(x=>x.id===id),exam:e,index,error:errors.find(x=>x.id===id)});}}return [...groups.values()].map(g=>{const recent=g.cases.slice(-3),correct=g.cases.filter(c=>c.clean).length;return {...g,total:g.cases.length,correct,recent:recent.filter(c=>c.clean).length,mastered:recent.length===3&&recent.every(c=>c.clean),lastError:g.cases.findLast(c=>!c.clean)};}).sort((a,b)=>(b.total-b.correct)-(a.total-a.correct)||a.key.localeCompare(b.key));}
